function runVM(instrs) {
  const stack = [];
  for (let pc = 0; pc < instrs.length; pc++) {
    const [op, arg] = instrs[pc];
    switch (op) {
      case 'PUSH': stack.push(arg); break;              // 값을 얹음
      case 'ADD': { const b = stack.pop(), a = stack.pop(); stack.push(a + b); break; }
      case 'MUL': { const b = stack.pop(), a = stack.pop(); stack.push(a * b); break; }
      // ... SUB, DIV 도 같은 꼴 (위 둘을 꺼내 결과를 얹음)
    }
  }
  return stack[0];   // 끝나면 스택에 답 하나
}
// 2+3*4: [2]→[2,3]→[2,3,4]→(MUL)[2,12]→(ADD)[14]

function compile(node, out = []) {
  if (node.kind === 'num') {
    out.push(['PUSH', node.value]);          // 숫자 → 값을 얹는 명령
    return out;
  }
  // 이항 연산: 자식 먼저(값을 쌓음), 연산자 나중(꺼내 계산)
  compile(node.left, out);                   // 왼쪽 → 스택에 값
  compile(node.right, out);                  // 오른쪽 → 스택에 값
  out.push([OPCODE[node.op]]);               // 연산자 → 위 둘을 꺼내 계산
  return out;
}
// evaluate 와 같은 재귀 구조 —
//   evaluate: 값을 즉시 계산해 반환
//   compile:  나중에 계산할 명령을 낸다 (실행을 미룸)

function run(instrs) {
  const stack = [];
  let pc = 0;                                 // 프로그램 카운터
  while (pc < instrs.length) {
    const [op, arg] = instrs[pc];             // fetch: 명령 가져오기
    switch (op) {                             // decode: op 코드 판별
      case 'PUSH': stack.push(arg); break;    // execute: 스택 조작
      case 'ADD': { const b=stack.pop(), a=stack.pop(); stack.push(a+b); break; }
      case 'JUMP': pc = arg; continue;        // 점프는 pc 를 바꿈(6장)
      // ...
    }
    pc++;                                     // 다음 명령으로
  }
  return stack[0];
}
